/* Bingo Pirámide 777 — textos en varios idiomas.
   Sin dependencias: un diccionario por idioma y una función t() para leerlo.
   El idioma es independiente del país: el país decide la moneda y el cobro;
   el idioma, los textos. Un jugador chino en Estados Unidos puede leer la mesa
   en chino y pagar en dólares. */

